import{_ as i,o as a,c as o,a5 as l}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Changelog: v1.x and earlier","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/older.md","filePath":"sections/changelog/older.md"}'),t={name:"sections/changelog/older.md"};function r(s,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog-v1-x-and-earlier" tabindex="-1">Changelog: v1.x and earlier <a class="header-anchor" href="#changelog-v1-x-and-earlier" aria-label="Permalink to &quot;Changelog: v1.x and earlier&quot;">​</a></h1><p>Brief per-version notes reconstructed from the RaiSim source history.</p><h2 id="v1-1-8-2024-04-07" tabindex="-1">v1.1.8 (2024-04-07) <a class="header-anchor" href="#v1-1-8-2024-04-07" aria-label="Permalink to &quot;v1.1.8 (2024-04-07)&quot;">​</a></h2><ul><li>Sensors: IMU methods, sensor getters/setters, modifiable sensor properties; sensor update no longer user-callable; depth order, IMU and timing fixes.</li><li>Mutexes for all objects and the world; visual heightmap.</li><li>Internal contact-count limit, joint velocity limit getter, named generalized-velocity indices; <code>base_link</code> accepted as fixed-base link.</li><li>Contact solver tuned for pin joints and closed loops; new Cholesky inverse; RK4 (single body), inverse dynamics and fixed-base nonlinearity fixes.</li><li>Fixed <code>setExternalForce</code> transpose, a contact segfault and transparency; <code>setupSocket</code> takes a port; dynamic visual meshes.</li><li>GCC builds, Linux debug build, macOS/M1 install fixes.</li></ul><h2 id="v1-1-7-2023-03-31" tabindex="-1">v1.1.7 (2023-03-31) <a class="header-anchor" href="#v1-1-7-2023-03-31" aria-label="Permalink to &quot;v1.1.7 (2023-03-31)&quot;">​</a></h2><ul><li>IMU sensor and inverse dynamics.</li><li>Dynamic heightmaps with per-vertex colours; collision shape parameter fix.</li><li>Configurable wire width in visualization.</li><li>Server protocol update; sensor freeze and parsing fixes.</li></ul><h2 id="v1-1-6-2022-12-04" tabindex="-1">v1.1.6 (2022-12-04) <a class="header-anchor" href="#v1-1-6-2022-12-04" aria-label="Permalink to &quot;v1.1.6 (2022-12-04)&quot;">​</a></h2><ul><li>Improved, faster contact solver.</li><li>Screenshot method, world-time display, server info on connect, <code>TimedLoop</code>.</li><li>Body type on object spawn; separate interaction-force function; improved world config files.</li><li>Fixed wire detach, generalized force errors and server getter ordering.</li></ul><h2 id="v1-1-5-2022-09-20" tabindex="-1">v1.1.5 (2022-09-20) <a class="header-anchor" href="#v1-1-5-2022-09-20" aria-label="Permalink to &quot;v1.1.5 (2022-09-20)&quot;">​</a></h2><ul><li><code>World::exportToXML</code> takes a single argument.</li><li><code>heightOffset</code> option and interaction mode for raisimUnreal.</li><li>MJCF loading, Windows debug postfix, contact visualization and object focus fixes.</li></ul><h2 id="v1-1-4-2022-08-27" tabindex="-1">v1.1.4 (2022-08-27) <a class="header-anchor" href="#v1-1-4-2022-08-27" aria-label="Permalink to &quot;v1.1.4 (2022-08-27)&quot;">​</a></h2><ul><li>Visual tags (new server mode) and <code>setMap</code>.</li><li>Sensor API clean-up; sensor frame and timing fixes.</li><li>Server reports request errors; Linux socket fix; joint-limit and robot visualization fixes.</li></ul><h2 id="v1-1-3-2022-07-24" tabindex="-1">v1.1.3 (2022-07-24) <a class="header-anchor" href="#v1-1-3-2022-07-24" aria-label="Permalink to &quot;v1.1.3 (2022-07-24)&quot;">​</a></h2><ul><li>New server protocol: visual instancing, synchronous mode, sensor data exchange (Unreal-compatible).</li><li>Non-blocking, safety-checked server socket with version-mismatch warning; collision body changes shown in visualization.</li><li><code>raisimODE</code> built with an SOVERSION; <code>setGeneralizedVelocity</code> no longer updates kinematics.</li></ul><h2 id="v1-1-2-2022-03-21" tabindex="-1">v1.1.2 (2022-03-21) <a class="header-anchor" href="#v1-1-2-2022-03-21" aria-label="Permalink to &quot;v1.1.2 (2022-03-21)&quot;">​</a></h2><ul><li>New SAP broad phase and ray test (large speed-up); static friction.</li><li>Initial sensors (URDF sensor reader, RealSense XML).</li><li>Velocity limits, spring APIs, Jacobian time derivative; external force/torque in body frame; URDF pin joints.</li><li>MJCF fixes (multiple joints, Euler order, refs, transparency); Cassie and Digit examples; default base joint is fixed.</li><li><code>getBodyIdx</code>/<code>getFrameIdx</code> return -1 when not found; heightmap and ray test fixes.</li><li>License tooling fixes; SOVERSION library versioning; Apple M1 CMake fix.</li></ul><h2 id="v1-1-0-2021-07-01" tabindex="-1">v1.1.0 (2021-07-01) <a class="header-anchor" href="#v1-1-0-2021-07-01" aria-label="Permalink to &quot;v1.1.0 (2021-07-01)&quot;">​</a></h2><ul><li>New ABA dynamics with contacts, joint limits and external forces; large speed-up.</li><li>Simplified contact solver; working self-collision.</li><li>MJCF reader (frames, defaults, assets/materials, ground, single bodies).</li><li>Fast Cholesky inverse; velocity computation separated from kinematics.</li></ul><h2 id="v1-0-5-2021-04-29" tabindex="-1">v1.0.5 (2021-04-29) <a class="header-anchor" href="#v1-0-5-2021-04-29" aria-label="Permalink to &quot;v1.0.5 (2021-04-29)&quot;">​</a></h2><ul><li>Server: video recording, ghost robots, external/contact force visualization, live visual shape changes, COM display.</li><li>XML: recursive compounds, wires, parameters with unresolved-name checks, lower-case element aliases.</li><li><code>setExternalForce</code> variants, clear external force/torque, PD getters, <code>setColor</code>, custom wires, joint-limit check, dynamic collision groups; <code>getLinkCOM</code> → <code>getBodyCOM</code>; <code>setLicenseFile</code> → <code>setActivationKey</code>.</li><li>RK4 integration (no contact), new articulated-system constructor, constraint/spring fixes, URDF materials.</li><li>Activation-key licensing (searched in <code>~/.raisim</code>); Windows and Apple M1 support; bundled Eigen.</li></ul><h2 id="v1-0-0-2020-05-04" tabindex="-1">v1.0.0 (2020-05-04) <a class="header-anchor" href="#v1-0-0-2020-05-04" aria-label="Permalink to &quot;v1.0.0 (2020-05-04)&quot;">​</a></h2><ul><li>New math library and frame Jacobians; Bullet and Python dependencies removed.</li><li>Worlds from XML (compounds, <code>[THIS_DIR]</code>, time step); capsule-box collision; heightmap normals and ray collision.</li><li>PD controller fixes, torque limits; base-only URDFs.</li><li>LTO (~15% faster); C++14; Windows, MATLAB and raisimUnity compatibility.</li></ul><h2 id="v0-7-0-2020-01-07" tabindex="-1">v0.7.0 (2020-01-07) <a class="header-anchor" href="#v0-7-0-2020-01-07" aria-label="Permalink to &quot;v0.7.0 (2020-01-07)&quot;">​</a></h2><ul><li>World loading from XML (articulated systems, heightmaps, meshes, visuals, object classes).</li><li>Server: add/remove visual objects, <code>hibernate()</code>/<code>wakeup()</code>, float data transfer.</li><li>Ray test; cleaned-up frame/joint methods; compliant wire, contact force and heightmap position fixes.</li><li>Removed <code>setBasePos</code>/<code>setBaseOrientation</code>; print movable joints.</li></ul><h2 id="v0-6-0-2019-10-29" tabindex="-1">v0.6.0 (2019-10-29) <a class="header-anchor" href="#v0-6-0-2019-10-29" aria-label="Permalink to &quot;v0.6.0 (2019-10-29)&quot;">​</a></h2><ul><li>Link/joint reference interface; access to collision and visual object sets.</li><li><code>setExternalTorque</code>; multiple articulated systems per URDF; URDF from string.</li><li>Server: configurable port, serialized contacts; <code>getObject</code> by index.</li><li>rpath on binaries; <code>getGravity</code> is const.</li></ul><h2 id="v0-5-0-2019-09-27" tabindex="-1">v0.5.0 (2019-09-27) <a class="header-anchor" href="#v0-5-0-2019-09-27" aria-label="Permalink to &quot;v0.5.0 (2019-09-27)&quot;">​</a></h2><ul><li>Improved ERP.</li><li>Mesh objects in the server; capsule and half-space server fixes.</li><li>Joint order fix; missing resource directory is a warning.</li></ul><h2 id="v0-4-x-2019-08-23-2019-09-06" tabindex="-1">v0.4.x (2019-08-23 – 2019-09-06) <a class="header-anchor" href="#v0-4-x-2019-08-23-2019-09-06" aria-label="Permalink to &quot;v0.4.x (2019-08-23 – 2019-09-06)&quot;">​</a></h2><ul><li>0.4.3: sparsity pattern fix.</li><li>0.4.2: ODE built as a shared library.</li><li>0.4.1: no space argument in the articulated-system constructor; matrix <code>()</code> operator.</li><li>0.4.0: mesh single bodies; more visualization methods.</li></ul><h2 id="v0-3-x-2019-08-13-2019-08-21" tabindex="-1">v0.3.x (2019-08-13 – 2019-08-21) <a class="header-anchor" href="#v0-3-x-2019-08-13-2019-08-21" aria-label="Permalink to &quot;v0.3.x (2019-08-13 – 2019-08-21)&quot;">​</a></h2><ul><li>0.3.1: dimension sanity checks.</li><li>0.3.0: <code>_W</code> suffix removed from method names.</li></ul><h2 id="v0-2-x-2019-07-13-2019-08-07" tabindex="-1">v0.2.x (2019-07-13 – 2019-08-07) <a class="header-anchor" href="#v0-2-x-2019-07-13-2019-08-07" aria-label="Permalink to &quot;v0.2.x (2019-07-13 – 2019-08-07)&quot;">​</a></h2><ul><li>0.2.1: shared library; change collision shape parameters, set material, get collision bodies by name, base pose getters; Python binding headers.</li><li>0.2.0: material system (<code>setDefaultMaterial</code>, <code>setMaterialPairProp</code>); objects/wires by name; actuation limits; actual generalized force getter.</li></ul><h2 id="v0-1-x-2019-04-10-2019-05-10" tabindex="-1">v0.1.x (2019-04-10 – 2019-05-10) <a class="header-anchor" href="#v0-1-x-2019-04-10-2019-05-10" aria-label="Permalink to &quot;v0.1.x (2019-04-10 – 2019-05-10)&quot;">​</a></h2><ul><li>0.1.2: heightmap from PNG; joint frame and solver state getters.</li><li>0.1.0: first versioned release — articulated systems, single bodies, compounds, heightmaps, meshes, wires; remote visualization server; Python interface.</li></ul>',36)])])}const v=i(t,[["render",r]]);export{m as __pageData,v as default};
